<?php
if(!defined('ABSPATH'))exit;
class InfoContainer_Admin_Diagnostic{
const TEST_SHA256='738058ab3581c712288647f79befee81cc359f52cc1377884423f270131bd8c6';
public function register(){add_management_page('Diagnóstico de InfoContainer','Diagnóstico de InfoContainer','manage_options','infocontainer-diagnostic',[$this,'render']);}
public function render(){if(!current_user_can('manage_options'))wp_die('No autorizado.','',['response'=>403]);$d=(new InfoContainer_Photo_Storage())->diagnostic();$rows=['Versión'=>INFOCONTAINER_VERSION,'ABSPATH'=>ABSPATH,'Document root PHP'=>isset($_SERVER['DOCUMENT_ROOT'])?(string)$_SERVER['DOCUMENT_ROOT']:'(no informado)','Raíz privada efectiva configurada'=>$d['configured'],'Existencia'=>$d['exists']?'Sí':'No','Ruta resuelta'=>$d['resolved']?:'(aún no existe)','Ubicación fuera de directorios públicos comprobables'=>$d['outside_public']?'Sí':'No / no determinable','Ancestro existente'=>$d['ancestor']?:'(no determinable)','Lectura del ancestro por PHP'=>$d['ancestor_readable']?'Sí':'No','Escritura del ancestro por PHP'=>$d['ancestor_writable']?'Sí':'No','Enlaces detectados'=>$d['links_in_path']?'Sí':'No detectados'];echo '<div class="wrap"><h1>Diagnóstico de InfoContainer</h1><style>.infocontainer-diagnostic-table{table-layout:fixed;max-width:1100px}.infocontainer-diagnostic-table th{width:32%}.infocontainer-diagnostic-table td{overflow-wrap:anywhere;word-break:break-word}.infocontainer-diagnostic-table tr:nth-child(even){background:#f6f7f7}</style><table class="widefat striped infocontainer-diagnostic-table"><tbody>';foreach($rows as $label=>$value)echo '<tr><th>'.esc_html($label).'</th><td>'.esc_html($value).'</td></tr>';echo '</tbody></table><p>Siguen pendientes: aliases, subdominios, CDN y reglas del servidor alojado. La consulta normal no crea carpetas, archivos, registros ni cambia permisos.</p>';if(isset($_GET['infocontainer_test_result']))echo '<div class="notice notice-info"><p>'.esc_html(sanitize_text_field(wp_unslash($_GET['infocontainer_test_result']))).'</p></div>';echo '<h2>Prueba de almacenamiento</h2><form method="post" action="'.esc_url(admin_url('admin-post.php')).'" enctype="multipart/form-data">';wp_nonce_field('infocontainer_storage_test','_infocontainer_storage_nonce');echo '<input type="file" name="infocontainer_test_file" accept="image/png" required><input type="hidden" name="action" value="infocontainer_storage_test"><button class="button button-primary">Ejecutar prueba explícita</button></form></div>';}
public function handle_test(){if(!current_user_can('manage_options')||!isset($_POST['_infocontainer_storage_nonce'])||!wp_verify_nonce(sanitize_text_field(wp_unslash($_POST['_infocontainer_storage_nonce'])),'infocontainer_storage_test'))wp_die('Solicitud no autorizada.','',['response'=>403]);$f=$_FILES['infocontainer_test_file']??[];if(!isset($f['tmp_name'])||!is_uploaded_file($f['tmp_name'])||hash_file('sha256',$f['tmp_name'])!==self::TEST_SHA256)return $this->redirect_result('Archivo rechazado: no coincide con el PNG autorizado.');$s=new InfoContainer_Photo_Storage();$v=$s->validate_upload($f);if(is_wp_error($v))return $this->redirect_result('Validación rechazada: '.$v->get_error_code());$key=$s->store($v);if(is_wp_error($key))return $this->redirect_result('Escritura fallida: '.$key->get_error_code());$h=null;$ok=false;$fail='';$clean=null;try{$h=$s->open($key);if(is_wp_error($h))$fail='apertura: '.$h->get_error_code();else{$st=fstat($h);$data=stream_get_contents($h);$ok=is_array($st)&&isset($st['size'])&&false!==$data&&(int)$st['size']===strlen($data)&&hash('sha256',$data)===self::TEST_SHA256;if(!$ok)$fail='lectura o integridad';}}catch(Throwable $e){$fail='excepción durante lectura';}finally{if(is_resource($h))fclose($h);try{$clean=$s->delete($key);}catch(Throwable $e){$clean=new WP_Error('cleanup_exception');}}if(is_wp_error($clean))return $this->redirect_result('Prueba incompleta: fallo de '.($fail?:'lectura').'; limpieza fallida.');$this->redirect_result($ok?'Prueba completada: creación, escritura, lectura, integridad y limpieza confirmadas.':'Prueba incompleta: fallo de '.($fail?:'lectura o integridad').'; limpieza confirmada.');}
private function redirect_result($m){wp_safe_redirect(add_query_arg(['page'=>'infocontainer-diagnostic','infocontainer_test_result'=>$m],admin_url('tools.php')));exit;}
}
